export type Method = keyof Methods;

/** The methods that answer with server-sent events, unless run in the background. */
export const STREAMING = ["goal/start", "thread/watch", "turn/start"] as const;

export type StreamingMethod = (typeof STREAMING)[number];

export type TaskFinishedParams = {
  readonly task: TaskInfo;
  readonly thread: ThreadId;
};

export type ThreadEventParams = {
  readonly event: RawEvent;
  readonly thread: ThreadId;
};

export type TurnLiveParams = {
  readonly thread: ThreadId;
  readonly update: Update;
};

/** What a server sends while a turn runs or a client watches. */
export type Notification =
  | { readonly jsonrpc: "2.0"; readonly method: "task/finished"; readonly params: TaskFinishedParams }
  | { readonly jsonrpc: "2.0"; readonly method: "thread/event"; readonly params: ThreadEventParams }
  | { readonly jsonrpc: "2.0"; readonly method: "turn/live"; readonly params: TurnLiveParams };

/** The error codes a request may be answered with. */
export const ErrorCode = {
  /** The thread is archived; unarchive it first */
  ARCHIVED: -32014,
  /** The operation was cancelled */
  CANCELLED: -32005,
  /** The git host refused, or could not be reached */
  HOST: -32025,
  /** The server failed */
  INTERNAL: -32603,
  /** The params are not valid */
  INVALID_PARAMS: -32602,
  /** The message is not a valid request */
  INVALID_REQUEST: -32600,
  /** A policy limit was reached */
  LIMIT: -32015,
  /** Memory is off for this server */
  MEMORY_OFF: -32018,
  /** The caller may not do this */
  NOT_ALLOWED: -32012,
  /** Not available yet, such as a thread on a computer of the person's own */
  NOT_AVAILABLE: -32022,
  /** No such approval is pending */
  NO_APPROVAL: -32004,
  /** No such command is running in the background in this thread */
  NO_COMMAND: -32027,
  /** No such git host, or sign-in, here */
  NO_CREDENTIAL: -32024,
  /** No such file here: never kept in this project, or no message used it within a day */
  NO_FILE: -32030,
  /** The project's folder isn't there anymore: give it its new place (`project/folder/set`) or remove the project (`project/remove`) */
  NO_FOLDER: -32029,
  /** The thread has no active goal (or, to resume, no paused one) */
  NO_GOAL: -32007,
  /** The thread's model does not read images */
  NO_IMAGES: -32031,
  /** No such memory here */
  NO_MEMORY: -32017,
  /** No such method */
  NO_METHOD: -32601,
  /** No such model here, or not one this server may run */
  NO_MODEL: -32021,
  /** No such project */
  NO_PROJECT: -32019,
  /** No such model account here */
  NO_PROVIDER: -32023,
  /** No such question is waiting */
  NO_QUESTION: -32006,
  /** No such schedule */
  NO_SCHEDULE: -32016,
  /** No valid sign-in (network transports) */
  NO_SIGN_IN: -32013,
  /** No such thread */
  NO_THREAD: -32001,
  /** No such ask waits: the project changed since, or asks nothing now */
  NO_TRUST: -32026,
  /** No turn is running in this thread */
  NO_TURN: -32003,
  /** The message is not JSON-RPC */
  PARSE: -32700,
  /** A hook stopped the prompt */
  PROMPT_BLOCKED: -32008,
  /** The model provider failed */
  PROVIDER: -32020,
  /** As many messages wait for the running turn as it takes */
  QUEUE_FULL: -32028,
  /** The thread is working on another server, which holds it */
  RUNNING_ELSEWHERE: -32011,
  /** A turn is already running in this thread */
  TURN_RUNNING: -32002,
  /** The thread's workspace could not be opened */
  WORKSPACE: -32009,
} as const;
